/*! GLightbox (minimal local build for Dreamy Cake)
 *  This is a lightweight, dependency-free implementation that matches the
 *  GLightbox API used by assets/js/main.js.
 */
(function () {
  'use strict';

  function createGLightbox(options) {
    const settings = options || {};
    const selector = String(settings.selector || '.glightbox');
    const loop = Boolean(settings.loop);
    const events = { open: [], close: [] };

    let elements = [];
    let container = null;
    let image = null;
    let caption = null;
    let previousButton = null;
    let nextButton = null;
    let isOpen = false;
    let activeGroup = null;
    let activeIndex = 0;
    let trigger = null;

    function emit(name) {
      (events[name] || []).forEach((callback) => {
        try {
          callback();
        } catch (_) {
          // Keep the lightbox responsive if a consumer callback fails.
        }
      });
    }

    function ensureContainer() {
      if (container) return;

      container = document.createElement('div');
      container.className = 'glightbox-container';
      container.hidden = true;
      container.setAttribute('role', 'dialog');
      container.setAttribute('aria-modal', 'true');
      container.setAttribute('aria-hidden', 'true');
      container.innerHTML = [
        '<div class="glightbox-overlay" data-gl-close></div>',
        '<button type="button" class="glightbox-close" aria-label="Close" data-gl-close>&times;</button>',
        '<button type="button" class="glightbox-prev" aria-label="Previous">&lsaquo;</button>',
        '<button type="button" class="glightbox-next" aria-label="Next">&rsaquo;</button>',
        '<div class="glightbox-content">',
        '<img class="glightbox-image" alt="" loading="eager"/>',
        '<div class="glightbox-caption"></div>',
        '</div>'
      ].join('');
      document.body.appendChild(container);

      image = container.querySelector('.glightbox-image');
      caption = container.querySelector('.glightbox-caption');
      previousButton = container.querySelector('.glightbox-prev');
      nextButton = container.querySelector('.glightbox-next');

      container.querySelectorAll('[data-gl-close]').forEach((element) => {
        element.addEventListener('click', close);
      });
      previousButton.addEventListener('click', previous);
      nextButton.addEventListener('click', next);
      document.addEventListener('keydown', onKeydown, true);
    }

    function onKeydown(event) {
      if (!isOpen) return;
      if (event.key === 'Escape') close();
      if (event.key === 'ArrowRight') next();
      if (event.key === 'ArrowLeft') previous();
    }

    function reload() {
      elements = Array.from(document.querySelectorAll(selector)).map((element) => {
        const href = element.getAttribute('href') || element.dataset.href || '';
        const gallery = element.getAttribute('data-gallery') || element.dataset.gallery || '';
        let title = element.getAttribute('data-title') || element.getAttribute('title') || '';
        const description = element.getAttribute('data-description') || '';
        if (!title) {
          const childImage = element.querySelector('img');
          if (childImage && childImage.getAttribute('alt')) title = childImage.getAttribute('alt');
        }
        return { element, href, gallery, title, description };
      });

      elements.forEach((item) => {
        if (!item.element || item.element.__glightboxBound) return;
        item.element.__glightboxBound = true;
        item.element.addEventListener('click', (event) => {
          if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
          event.preventDefault();
          open(item.element);
        });
      });
    }

    function groupFor(element) {
      const gallery = (element.getAttribute('data-gallery') || element.dataset.gallery || '').trim();
      if (gallery) {
        return { gallery, items: elements.filter((item) => item.gallery === gallery) };
      }
      const item = elements.find((entry) => entry.element === element);
      return {
        gallery: '',
        items: item
          ? [item]
          : [{ element, href: element.getAttribute('href') || '', gallery: '', title: '', description: '' }]
      };
    }

    function open(element) {
      ensureContainer();
      reload();
      trigger = element;
      activeGroup = groupFor(element);
      activeIndex = activeGroup.items.findIndex((item) => item.element === element);
      if (activeIndex < 0) activeIndex = 0;
      openAt(activeIndex);
    }

    function render() {
      if (!activeGroup || !activeGroup.items.length) return;
      const item = activeGroup.items[activeIndex];
      if (!item) return;

      image.alt = item.title || '';
      image.src = item.href || '';
      const title = (item.title || '').trim();
      const description = (item.description || '').trim();
      const text = title && description ? `${title} — ${description}` : title || description || '';
      caption.textContent = text;
      caption.style.display = text ? '' : 'none';

      const hasNavigation = activeGroup.items.length > 1;
      previousButton.hidden = !hasNavigation;
      nextButton.hidden = !hasNavigation;
      if (hasNavigation) {
        previousButton.disabled = !loop && activeIndex <= 0;
        nextButton.disabled = !loop && activeIndex >= activeGroup.items.length - 1;
      }
    }

    function openAt(index) {
      if (!activeGroup || !activeGroup.items.length) return;
      activeIndex = Math.max(0, Math.min(index, activeGroup.items.length - 1));
      container.hidden = false;
      container.setAttribute('aria-hidden', 'false');
      document.body.classList.add('glightbox-open');
      isOpen = true;
      render();
      setTimeout(() => {
        try {
          container.querySelector('.glightbox-close').focus();
        } catch (_) {
          // Focus is a progressive enhancement.
        }
      }, 0);
      emit('open');
    }

    function close() {
      if (!container || !isOpen) return;
      isOpen = false;
      try {
        if (trigger && trigger.focus) trigger.focus({ preventScroll: true });
      } catch (_) {
        // Older browsers may not support the focus options object.
      }
      container.setAttribute('aria-hidden', 'true');
      container.hidden = true;
      document.body.classList.remove('glightbox-open');
      emit('close');
    }

    function next() {
      if (!activeGroup || !isOpen || !activeGroup.items.length) return;
      if (activeIndex < activeGroup.items.length - 1) activeIndex += 1;
      else if (loop) activeIndex = 0;
      render();
    }

    function previous() {
      if (!activeGroup || !isOpen || !activeGroup.items.length) return;
      if (activeIndex > 0) activeIndex -= 1;
      else if (loop) activeIndex = activeGroup.items.length - 1;
      render();
    }

    reload();
    return {
      on(name, callback) {
        if (!events[name]) events[name] = [];
        if (typeof callback === 'function') events[name].push(callback);
        return this;
      },
      open,
      openAt,
      close,
      nextSlide: next,
      prevSlide: previous,
      reload,
      destroy() {
        close();
        if (container && container.parentNode) container.parentNode.removeChild(container);
        container = null;
      }
    };
  }

  window.GLightbox = createGLightbox;
  window.GLightbox.version = 'local-1.1';
})();
